export const MAX_SAVE_BYTES=67108864,MAX_CHUNK_DECOMP_BYTES=4194304,MAX_TOTAL_DECOMP_BYTES=100663296,MAX_CHUNKS=512,MAX_JSON_DEPTH=48,MAX_INFLATED_BYTES=4194304,MAX_RECORDS=8192,MAX_SYSTEMS=16384,MAX_NAME_LEN=64,MAX_USER_LEN=32,MAX_ARRAY_LEN=8192,MAX_UA_HEX_LEN=32;export function boundedArray(t,e=8192){return Array.isArray(t)?t.slice(0,e):[]}export const MAX_PLAUSIBLE_TS=Date.UTC(2100,0,1)/1e3,MIN_PLAUSIBLE_TS=Date.UTC(2016,7,9)/1e3;export function sanitizeString(t,e){if(typeof t!="string"||!t.length)return null;const n=t.replace(/[\x00-\x1f\x7f-\u009f]/g,"");return n.length?n.slice(0,e):null}export function sanitizeTs(t){return typeof t=="number"&&Number.isFinite(t)&&t>=MIN_PLAUSIBLE_TS&&t<MAX_PLAUSIBLE_TS?t:null}
